41		static readonly configName = 'editor.defaultFormatter';
42	
43		static extensionIds: (string | null)[] = [];
44		static extensionItemLabels: string[] = [];
45		static extensionDescriptions: string[] = [];
46	
47		private readonly _languageStatusStore = this._store.add(new DisposableStore());
48	
49		constructor(
50			@IExtensionService private readonly _extensionService: IExtensionService,
51			@IWorkbenchExtensionEnablementService private readonly _extensionEnablementService: IWorkbenchExtensionEnablementService,
52			@IConfigurationService private readonly _configService: IConfigurationService,
53			@INotificationService private readonly _notificationService: INotificationService,
54			@IDialogService private readonly _dialogService: IDialogService,
55			@IQuickInputService private readonly _quickInputService: IQuickInputService,
56			@ILanguageService private readonly _languageService: ILanguageService,
57			@ILanguageFeaturesService private readonly _languageFeaturesService: ILanguageFeaturesService,
58			@ILanguageStatusService private readonly _languageStatusService: ILanguageStatusService,
59			@IEditorService private readonly _editorService: IEditorService,
60		) {
61			super();
62			this._store.add(this._extensionService.onDidChangeExtensions(this._updateConfigValues, this));
63			this._store.add(FormattingConflicts.setFormatterSelector((formatter, document, mode, kind) => this._selectFormatter(formatter, document, mode, kind)));
64			this._store.add(_editorService.onDidActiveEditorChange(this._updateStatus, this));
65			this._store.add(_languageFeaturesService.documentFormattingEditProvider.onDidChange(this._updateStatus, this));
66			this._store.add(_languageFeaturesService.documentRangeFormattingEditProvider.onDidChange(this._updateStatus, this));
67			this._store.add(_languageFeaturesService.documentFormattingEditProvider.onDidChange(this._updateConfigValues, this));
68			this._store.add(_languageFeaturesService.documentRangeFormattingEditProvider.onDidChange(this._updateConfigValues, this));
69			this._store.add(_configService.onDidChangeConfiguration(e => e.affectsConfiguration(DefaultFormatter.configName) && this._updateStatus()));
70			this._updateConfigValues();
71		}
72	
73		private async _updateConfigValues(): Promise<void> {
74			await this._extensionService.whenInstalledExtensionsRegistered();
75			let extensions = [...this._extensionService.extensions];
76	
77			// Get all formatter providers to identify which extensions actually contribute formatters
78			const documentFormatters = this._languageFeaturesService.documentFormattingEditProvider.allNoModel();
79			const rangeFormatters = this._languageFeaturesService.documentRangeFormattingEditProvider.allNoModel();
80			const formatterExtensionIds = new Set<string>();
81	
82			for (const formatter of documentFormatters) {
83				if (formatter.extensionId) {
84					formatterExtensionIds.add(ExtensionIdentifier.toKey(formatter.extensionId));
85				}
86			}
87			for (const formatter of rangeFormatters) {
88				if (formatter.extensionId) {
89					formatterExtensionIds.add(ExtensionIdentifier.toKey(formatter.extensionId));
90				}
91			}
92	
93			extensions = extensions.sort((a, b) => {
94				// Ultimate boost: extensions that actually contribute formatters
95				const contributesFormatterA = formatterExtensionIds.has(ExtensionIdentifier.toKey(a.identifier));
96				const contributesFormatterB = formatterExtensionIds.has(ExtensionIdentifier.toKey(b.identifier));
97	
98				if (contributesFormatterA && !contributesFormatterB) {
99					return -1;
100				} else if (!contributesFormatterA && contributesFormatterB) {
101					return 1;
102				}
103	
104				// Secondary boost: category-based sorting
105				const boostA = a.categories?.find(cat => cat === 'Formatters' || cat === 'Programming Languages');
106				const boostB = b.categories?.find(cat => cat === 'Formatters' || cat === 'Programming Languages');
107	
108				if (boostA && !boostB) {
109					return -1;
110				} else if (!boostA && boostB) {
111					return 1;
112				} else {
113					return a.name.localeCompare(b.name);
114				}
115			});
116	
117			DefaultFormatter.extensionIds.length = 0;
118			DefaultFormatter.extensionItemLabels.length = 0;
119			DefaultFormatter.extensionDescriptions.length = 0;
120	
121			DefaultFormatter.extensionIds.push(null);
122			DefaultFormatter.extensionItemLabels.push(nls.localize('null', 'None'));
123			DefaultFormatter.extensionDescriptions.push(nls.localize('nullFormatterDescription', "None"));
124	
125			for (const extension of extensions) {
126				if (extension.main || extension.browser) {
127					DefaultFormatter.extensionIds.push(extension.identifier.value);
128					DefaultFormatter.extensionItemLabels.push(extension.displayName ?? '');
129					DefaultFormatter.extensionDescriptions.push(extension.description ?? '');
130				}
131			}
132		}
133	
134		static _maybeQuotes(s: string): string {
135			return s.match(/\s/) ? `'${s}'` : s;
136		}
137	
138		private async _analyzeFormatter<T extends FormattingEditProvider>(kind: FormattingKind, formatter: T[], document: ITextModel): Promise<T | string> {
139			const defaultFormatterId = this._configService.getValue<string>(DefaultFormatter.configName, {
140				resource: document.uri,
141				overrideIdentifier: document.getLanguageId()
142			});
143	
144			if (defaultFormatterId) {
145				// good -> formatter configured
146				const defaultFormatter = formatter.find(formatter => ExtensionIdentifier.equals(formatter.extensionId, defaultFormatterId));
147				if (defaultFormatter) {
148					// formatter available
149					return defaultFormatter;
150				}
151	
152				// bad -> formatter gone
153				const extension = await this._extensionService.getExtension(defaultFormatterId);
154				if (extension && this._extensionEnablementService.isEnabled(toExtension(extension))) {
155					// formatter does not target this file
156					const langName = this._languageService.getLanguageName(document.getLanguageId()) || document.getLanguageId();
157					const detail = kind === FormattingKind.File
158						? nls.localize('miss.1', "Extension '{0}' is configured as formatter but it cannot format '{1}'-files", extension.displayName || extension.name, langName)
159						: nls.localize('miss.2', "Extension '{0}' is configured as formatter but it can only format '{1}'-files as a whole, not selections or parts of it.", extension.displayName || extension.name, langName);
160					return detail;
161				}
162	
163			} else if (formatter.length === 1) {
164				// ok -> nothing configured but only one formatter available
165				return formatter[0];
166			}
167	
168			const langName = this._languageService.getLanguageName(document.getLanguageId()) || document.getLanguageId();
169			const message = !defaultFormatterId
170				? nls.localize('config.needed', "There are multiple formatters for '{0}' files. One of them should be configured as default formatter.", DefaultFormatter._maybeQuotes(langName))
171				: nls.localize('config.bad', "Extension '{0}' is configured as formatter but not available. Select a different default formatter to continue.", defaultFormatterId);
172	
173			return message;
174		}
175	
176		private async _selectFormatter<T extends FormattingEditProvider>(formatter: T[], document: ITextModel, mode: FormattingMode, kind: FormattingKind): Promise<T | undefined> {
177			const formatterOrMessage = await this._analyzeFormatter(kind, formatter, document);
178			if (typeof formatterOrMessage !== 'string') {
179				return formatterOrMessage;
180			}
